  const fmSettings = settings.floodMitigation || {};
  const floodGeo = drainCtxData?.floodGeo || null;
  const fmZones = (floodGeo && floodGeo.zones) || [];
  // NEW-9 (pond-roles branch) — a restored (remembered) view has no flood polygons, so
