  const fmDerivedBfe = floodGeo?.derivedBfe || null;
  // B762 — the governing 1% WSEL derived from FEMA cross-sections (its own field, never
  // overwriting a manual BFE; used in precedence only when no static/manual BFE exists).
  const fmDerivedXsWsel = floodGeo?.derivedXsWsel || null;
  // Elevation intermediates that DON'T depend on the pad — computed first so the AUTO
  // pad (NEW-3) can be derived from them before fmElev is assembled.
  const fmManualPadFt = Number.isFinite(fmSettings.padFfeFt) ? fmSettings.padFfeFt : null;
  const fmManualBfeFt = Number.isFinite(fmSettings.bfeFt) ? fmSettings.bfeFt : null;
  const fmDerivedBfeFt = fmDerivedBfe && Number.isFinite(fmDerivedBfe.bfeFt) ? fmDerivedBfe.bfeFt : null;
  const fmDerivedXsWselFt = fmDerivedXsWsel && Number.isFinite(fmDerivedXsWsel.wselFt) ? fmDerivedXsWsel.wselFt : null;
  const fmManualWse02Ft = Number.isFinite(fmSettings.wse02Ft) ? fmSettings.wse02Ft : null;
  const fmDerivedWse02Ft = floodGeo?.derivedWse02 && Number.isFinite(floodGeo.derivedWse02.wseFt) ? floodGeo.derivedWse02.wseFt : null;
  // B807 — the DRAFT Atlas-14 1% WSE from the per-watershed rasters (Fort Bend only).
  const fmDerivedWse100Ft = floodGeo?.derivedWse100 && Number.isFinite(floodGeo.derivedWse100.wseFt) ? floodGeo.derivedWse100.wseFt : null;
  // B882 — the pluggable estimated-WSE providers for unstudied Zone A: HCFCD MAAPnext (Harris,
  // scope note 2), FEMA InFRM EBFE (any county), and FBCDD (Fort Bend, already fetched above).
  // The 0.2% (500-yr) field fills by the SAME precedence (district → EBFE); a manual entry still
  // overrides downstream. Precedence + provenance live in lib/wseProviders.js (one registry).
  const fmEbfe = floodGeo?.ebfe || null;
  const fmEbfeBfe1pctFt = fmEbfe && Number.isFinite(fmEbfe.bfe1pctFt) ? fmEbfe.bfe1pctFt : null;
  const fmEbfeWse02Ft = fmEbfe && Number.isFinite(fmEbfe.wse02Ft) ? fmEbfe.wse02Ft : null;
  const fmMaapnext = floodGeo?.maapnext || null;
  const fmMaapnextWse1pctFt = fmMaapnext && Number.isFinite(fmMaapnext.wse1pctFt) ? fmMaapnext.wse1pctFt : null;
  const fmMaapnextWse02Ft = fmMaapnext && Number.isFinite(fmMaapnext.wse02Ft) ? fmMaapnext.wse02Ft : null;
  const fmDrainCounty = drainCtxData?.authority?.jurisdiction?.county || [];
  // NEW-1 (B1057 completion) — Planyr's own screening study, computed at check time from live
  // inputs (D8 watershed + Atlas 14 + SSURGO + a 3DEP section). It is the ONLY provider whose 1%
  // and 0.2% come from one derivation, which is what lets the two fields agree by construction.
  // A `{ok:false}` result contributes NOTHING to the registry — an unknown never becomes a value.
  const fmScreeningBfe = floodGeo?.screeningBfe || null;
  const fmScreeningOk = !!(fmScreeningBfe && fmScreeningBfe.ok);
  const fmScreeningWse1pctFt = fmScreeningOk && Number.isFinite(fmScreeningBfe.wse1pctFt) ? fmScreeningBfe.wse1pctFt : null;
  const fmScreeningWse02Ft = fmScreeningOk && Number.isFinite(fmScreeningBfe.wse02pctFt) ? fmScreeningBfe.wse02pctFt : null;
  // The registry candidates that carry a 0.2% (grade has none) — resolved by county precedence.
  const fmWse02Candidates = {
    maapnext: fmMaapnext ? { wse1pctFt: fmMaapnextWse1pctFt, wse02Ft: fmMaapnextWse02Ft } : null,
    fbcdd: (fmDerivedWse100Ft != null || fmDerivedWse02Ft != null) ? { wse1pctFt: fmDerivedWse100Ft, wse02Ft: fmDerivedWse02Ft } : null,
    ebfe: (fmEbfeBfe1pctFt != null || fmEbfeWse02Ft != null) ? { wse1pctFt: fmEbfeBfe1pctFt, wse02Ft: fmEbfeWse02Ft } : null,
    screeningBfe: (fmScreeningWse1pctFt != null || fmScreeningWse02Ft != null) ? { wse1pctFt: fmScreeningWse1pctFt, wse02Ft: fmScreeningWse02Ft } : null,
    grade: null,
  };
  const fmWse02Resolved = resolveEstimatedWse({ county: fmDrainCounty, candidates: fmWse02Candidates });
  const fmDerivedWse02FtEff = fmWse02Resolved?.wse02Ft ?? null;
  const fmDerivedWse02SrcEff = fmWse02Resolved?.wse02Src ?? null;
  // Governing 1% WSE for buildability/FFE: highest published static BFE → manual → the
  // derived XS WSEL → the derived BFE-line estimate (same precedence the engine uses).
  // Deliberately EXCLUDES the DRAFT Atlas-14 100-yr (fmDerivedWse100Ft) — a draft study
  // value must never masquerade as the FIRM-BFE basis; it enters FFE only through its
  // own labeled atlas14_100yr basis (below) and the mitigation chain's last rung.
  const fmGoverningBfe = fmZones.reduce((best, z) => (z.staticBfeFt != null && (best == null || z.staticBfeFt > best) ? z.staticBfeFt : best), null) ?? fmManualBfeFt ?? fmDerivedXsWselFt ?? fmDerivedBfeFt;
  // NEW-3 — the AUTO pad: the code-minimum required FFE from the buildability rule. The
  // owner shouldn't have to type a pad on a floodplain fill — the code (FBC: 2′ above the
  // 500-yr, or the governing basis) dictates the minimum. When no pad is entered we assume
  // the site builds to this floor, so mitigation prices WSE-governed (pad ≥ WSE by
  // construction) instead of blocking on a missing FFE. A typed pad still overrides.
  const fmBuildRule = buildRules[floodJurKey] || buildRules.generic;
  // B808 — the per-cell existing-grade sampler off the site-extent DEM grid (a manual
  // grade wins — the engine gates on sources.existGrade "manual" as well; the 3DEP
  // median stays the labeled fallback whenever the grid didn't load). Hoisted above the
  // AUTO FFE so the NEW-2 estimator and the NEW-3 HAG proxy can feed it.
  const fmDemGrid = floodGeo?.demGrid && floodGeo.demGrid.state === "loaded" && floodGeo.demGrid.grid ? floodGeo.demGrid : null;
  const fmGradeAt = fmDemGrid && !Number.isFinite(fmSettings.existGradeFt)
    ? (pt) => { const gll = feetToLatLng(pt, origin.lat, origin.lon); return sampleAtLatLng(fmDemGrid.grid, fmDemGrid.req, gll[0], gll[1]); }
    : null;
  // NEW-1 (Waller) / NEW-3 — location ctx for `when`-conditioned FFE bases, computed from
